edits.replace:
if data_element.is_raw:
    # raw data element values can be written as they are
    # but if the value is a list, convert to a proper DataElement first
    if isinstance(data_element.value, list):
        data_element = DataElement_from_raw(data_element)
        VR = data_element.VR
        if VR == 'SQ':
            write_sequence(buffer, data_element, encodings)
            is_undefined_length = data_element.is_undefined_length
        else:
            if VR not in writers:
                raise NotImplem
            writer = writers[VR]
            writer(buffer, data_element, encodings)
            is_undefined_length = data_element.is_undefined_length
    else:
        buffer.write(data_element.value)
        is_undefined_length = data_element.length == 0xFFFFFFFF
else:
    if VR not in writers:
        raise NotImplem
